import os, json, csv, math, time, hashlib, itertools
import numpy as np

# Paths
N = 26
SHARED_DIR = 'storage/shared/appxE_contribs'
P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
P_SUMMARY = 'storage/noesis/nmap/appendix_E_summary.json'
RESULTS_DIR = 'storage/noesis/nmap/results'

# ----------------- Helpers -----------------
def sha256_hex(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    return c, r

def boundary_from_snapshot(c, r, tol):
    S = set()
    x, y = c[:,0], c[:,1]
    sl = x - r
    sr = 1.0 - x - r
    sb = y - r
    st = 1.0 - y - r
    for i in range(N):
        if sl[i] <= tol: S.add((i,'xL'))
        if sr[i] <= tol: S.add((i,'xR'))
        if sb[i] <= tol: S.add((i,'yB'))
        if st[i] <= tol: S.add((i,'yT'))
    return S

def jaccard(a, b):
    A = set(a); B = set(b)
    inter = len(A & B); uni = len(A | B)
    return inter, uni, (inter/uni) if uni>0 else 1.0

def segs_cross(p, q, r, s, inclusive=False, eps=1e-12):
    def orient(a,b,c):
        return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])
    def on_seg(a,b,c):
        return (min(a[0],b[0])-eps <= c[0] <= max(a[0],b[0])+eps and
                min(a[1],b[1])-eps <= c[1] <= max(a[1],b[1])+eps)
    o1 = orient(p,q,r); o2 = orient(p,q,s); o3 = orient(r,s,p); o4 = orient(r,s,q)
    if (o1*o2 < -eps) and (o3*o4 < -eps):
        return True
    if inclusive:
        if abs(o1) <= eps and on_seg(p,q,r): return True
        if abs(o2) <= eps and on_seg(p,q,s): return True
        if abs(o3) <= eps and on_seg(r,s,p): return True
        if abs(o4) <= eps and on_seg(r,s,q): return True
    return False

def pairs_slack_topK(c, r, tol, K):
    # Top-K by smallest slack among pairs with slack <= tol (may return <K if few pass tol)
    items = []
    for i in range(N):
        for j in range(i+1, N):
            d = float(math.hypot(c[i,0]-c[j,0], c[i,1]-c[j,1]))
            s = d - (r[i] + r[j])
            if s <= tol:
                items.append((s, i, j))
    items.sort(key=lambda t: (t[0], t[1], t[2]))
    pairs = [(i,j) for _,i,j in items[:K]]
    return set(pairs), { (i,j): s for s,i,j in items[:min(K, len(items))] }

def valid_disc(i): return isinstance(i, int) and 0 <= i < N

# ----------------- Parsing -----------------
def parse_json(path):
    data = json.load(open(path, 'r', encoding='utf-8'))
    eval_id = int(data.get('eval_id'))
    boundary = [(int(x['disc']), str(x['side'])) for x in data.get('boundary', [])]
    topk = {}
    for item in data.get('topk', []):
        m = str(item.get('method'))
        tol = str(item.get('tol'))
        K = int(item.get('K', 0))
        pairs = [tuple(map(int,p)) for p in item.get('pairs', [])]
        topk[(m, tol, K)] = set((min(i,j), max(i,j)) for (i,j) in pairs if valid_disc(i) and valid_disc(j) and i<j)
    return eval_id, boundary, topk

def parse_csv(path):
    # Detect by headers: boundary (disc,side) vs pairs (method,tol,K,i,j)
    boundary = []
    topk = {}
    eval_id = None
    with open(path, 'r', encoding='utf-8') as f:
        rdr = csv.DictReader(f)
        headers = [h.strip() for h in rdr.fieldnames or []]
        if {'disc','side'}.issubset(set(headers)):
            # Boundary rows
            for row in rdr:
                if 'eval_id' in row and row['eval_id']:
                    try: eval_id = int(row['eval_id'])
                    except: pass
                try:
                    boundary.append((int(row['disc']), str(row['side'])))
                except: pass
        else:
            # Pairs rows
            for row in rdr:
                if eval_id is None and 'eval_id' in row and row['eval_id']:
                    try: eval_id = int(row['eval_id'])
                    except: pass
                try:
                    m = str(row['method']).strip()
                    tol = str(row['tol']).strip()
                    K = int(row['K'])
                    i = int(row['i']); j = int(row['j'])
                    if valid_disc(i) and valid_disc(j) and i<j:
                        key = (m, tol, K)
                        if key not in topk: topk[key] = set()
                        topk[key].add((i,j))
                except: pass
    return eval_id if eval_id is not None else 0, boundary, topk

def load_contrib(path):
    try:
        if path.lower().endswith('.json'):
            return parse_json(path)
        elif path.lower().endswith('.csv'):
            return parse_csv(path)
    except Exception as e:
        print('PARSE_ERROR', path, repr(e))
    return None

# ----------------- Aggregation -----------------
def integrate_one(c, r, fname, eval_id, boundary_list, topk_map):
    name = os.path.splitext(os.path.basename(fname))[0]
    # Validate boundary
    boundary_set = set((int(i), str(s)) for (i,s) in boundary_list if valid_disc(int(i)) and str(s) in {'xL','xR','yB','yT'})
    status = 'ok'
    if len(boundary_set) != 20:
        status = 'incomplete_boundary'

    # Noesis boundary at tolerances
    b_noe_2e8 = boundary_from_snapshot(c, r, 2e-8)
    b_noe_1e8 = boundary_from_snapshot(c, r, 1e-8)
    inter_b, uni_b, J_b = jaccard(boundary_set, b_noe_2e8)

    # Prepare Top-K (slack only)
    other_k25_1e9 = topk_map.get(('slack','1e-9',25), set())
    other_k15_1e8 = topk_map.get(('slack','1e-8',15), set())
    # Noesis Top-K lists
    noe_k25_1e9, _ = pairs_slack_topK(c, r, 1e-9, 25)
    noe_k15_1e8, _ = pairs_slack_topK(c, r, 1e-8, 15)

    inter25, uni25, J25 = jaccard(other_k25_1e9, noe_k25_1e9)
    inter15, uni15, J15 = jaccard(other_k15_1e8, noe_k15_1e8)

    # Gate v1 on Noesis geometry
    dual = other_k25_1e9 & other_k15_1e8
    # Interior filter by Noesis boundary@1e-8
    bd_discs_1e8 = set(i for (i,_) in b_noe_1e8)
    dual_int = set((i,j) for (i,j) in dual if (i not in bd_discs_1e8 and j not in bd_discs_1e8))

    # Crossing checks
    strict = False; inclusive = False
    examples = []
    pts = [tuple(c[i]) for i in range(N)]
    for (i,j),(k,l) in itertools.combinations(dual_int, 2):
        if len({i,j,k,l}) < 4:  # disjoint endpoints only
            continue
        if segs_cross(pts[i], pts[j], pts[k], pts[l], inclusive=False):
            strict = True
            if len(examples) < 10:
                examples.append(((i,j),(k,l)))
        if segs_cross(pts[i], pts[j], pts[k], pts[l], inclusive=True):
            inclusive = True

    # Count both_near_active@1e-8 among strict examples
    both_near = 0
    pair_slack = {}
    for i in range(N):
        for j in range(i+1, N):
            d = float(math.hypot(c[i,0]-c[j,0], c[i,1]-c[j,1]))
            pair_slack[(i,j)] = d - (r[i] + r[j])
    for (i,j),(k,l) in examples:
        if pair_slack[(i,j)] <= 1e-8 and pair_slack[(k,l)] <= 1e-8:
            both_near += 1

    # Build result object
    res = {
        "source": name,
        "eval_ref": int(eval_id),
        "status": status,
        "boundary_jaccard": {"2e-8": J_b, "inter": inter_b, "union": uni_b},
        "topk_jaccards_slack": {
            "K25@1e-9": J25, "K15@1e-8": J15,
            "intersections": {"K25": inter25, "K15": inter15},
            "unions": {"K25": uni25, "K15": uni15}
        },
        "gate_v1_on_noesis": {
            "dual_intersection_size": len(dual),
            "dual_interior_size": len(dual_int),
            "sat_strict": strict,
            "sat_inclusive": inclusive,
            "examples": examples,
            "both_near_active_at_1e-8": both_near
        }
    }
    os.makedirs(RESULTS_DIR, exist_ok=True)
    out_path = os.path.join(RESULTS_DIR, f"{name}_compare.json")
    with open(out_path, 'w', encoding='utf-8') as f:
        json.dump(res, f, indent=2)
    print("RESULTS_FILE:", out_path)
    return res

def update_summary(summary, res, file_hash):
    entries = summary.get("entries", [])
    # Identify by "source" name
    updated = False
    for ent in entries:
        if ent.get("lineage") == res["source"] or ent.get("source") == res["source"]:
            # Update in place
            ent.update({
                "lineage": res["source"],
                "eval_ref": res["eval_ref"],
                "boundary_jaccard": {"2e-8": res["boundary_jaccard"]["2e-8"]},
                "topk_jaccards_slack": {
                    "K25@1e-9": res["topk_jaccards_slack"]["K25@1e-9"],
                    "K15@1e-8": res["topk_jaccards_slack"]["K15@1e-8"]
                },
                "gate_v1_on_noesis": {
                    "dual_intersection_size": res["gate_v1_on_noesis"]["dual_intersection_size"],
                    "dual_interior_size": res["gate_v1_on_noesis"]["dual_interior_size"],
                    "sat_strict": res["gate_v1_on_noesis"]["sat_strict"],
                    "sat_inclusive": res["gate_v1_on_noesis"]["sat_inclusive"],
                    "examples_count": len(res["gate_v1_on_noesis"]["examples"]),
                    "both_near_active_at_1e-8": res["gate_v1_on_noesis"]["both_near_active_at_1e-8"]
                },
                "source_hash": file_hash
            })
            updated = True
            break
    if not updated:
        entries.append({
            "lineage": res["source"],
            "eval_ref": res["eval_ref"],
            "boundary_jaccard": {"2e-8": res["boundary_jaccard"]["2e-8"]},
            "topk_jaccards_slack": {
                "K25@1e-9": res["topk_jaccards_slack"]["K25@1e-9"],
                "K15@1e-8": res["topk_jaccards_slack"]["K15@1e-8"]
            },
            "gate_v1_on_noesis": {
                "dual_intersection_size": res["gate_v1_on_noesis"]["dual_intersection_size"],
                "dual_interior_size": res["gate_v1_on_noesis"]["dual_interior_size"],
                "sat_strict": res["gate_v1_on_noesis"]["sat_strict"],
                "sat_inclusive": res["gate_v1_on_noesis"]["sat_inclusive"],
                "examples_count": len(res["gate_v1_on_noesis"]["examples"]),
                "both_near_active_at_1e-8": res["gate_v1_on_noesis"]["both_near_active_at_1e-8"]
            },
            "source_hash": file_hash
        })
    summary["entries"] = entries
    return summary

# ----------------- Main -----------------
def construct_packing():
    c, r = load_snapshot()
    os.makedirs(RESULTS_DIR, exist_ok=True)

    # Load or init summary
    try:
        with open(P_SUMMARY, 'r', encoding='utf-8') as f:
            summary = json.load(f)
    except Exception:
        summary = {"meta": {"protocol_file": "storage/noesis/nmap/appendix_E_protocol_v1.json",
                             "geometry": "Noesis snapshot (latest_centers.txt/latest_radii.txt)"},
                   "entries": []}
    meta = summary.setdefault("meta", {})
    seen_hashes = set()
    file_list = []

    if os.path.isdir(SHARED_DIR):
        for fname in os.listdir(SHARED_DIR):
            if not fname.lower().endswith(('.json', '.csv')): continue
            path = os.path.join(SHARED_DIR, fname)
            try:
                file_hash = sha256_hex(path)
            except Exception:
                continue
            file_list.append((path, file_hash))

    processed = 0
    for path, fh in file_list:
        # Skip if already integrated with same hash
        already = False
        for ent in summary.get("entries", []):
            if ent.get("source_hash") == fh:
                already = True; break
        if already:
            print("SKIP_DUP_HASH:", path)
            continue

        payload = load_contrib(path)
        if payload is None:
            print("SKIP_PARSE_FAIL:", path)
            continue
        eval_id, boundary, topk = payload
        res = integrate_one(c, r, path, eval_id, boundary, topk)
        summary = update_summary(summary, res, fh)
        processed += 1

    # Update meta timestamps
    meta["aggregator_last_run"] = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    meta["aggregator_files_seen"] = len(file_list)
    meta["aggregator_files_processed"] = processed

    with open(P_SUMMARY, 'w', encoding='utf-8') as f:
        json.dump(summary, f, indent=2)
    print("SUMMARY_UPDATED:", P_SUMMARY, "FILES_PROCESSED:", processed)

    # Return baseline with tiny shrink
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
